{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body>
  <header class="nav">
    <div class="brand">
      <a href="index.html" class="logo">{{BUSINESS_NAME}}</a>
      <span class="sub">{{CITY}}, {{STATE}}</span>
    </div>
    <nav>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Private</a>
      <a href="pricing.html">Rates</a>
      <a href="about.html">The Space</a>
      <a href="faq.html">Questions</a>
      <a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="card glass">
        <h1>Sound alchemy for the everyday pause</h1>
        <p class="lead">{{TAGLINE}}</p>

        <div class="mixer" id="mixer">
          <label>Choose sound intensity</label>
          <div class="controls">
            <button data-intensity="gentle" class="active">Gentle</button>
            <button data-intensity="medium">Medium</button>
            <button data-intensity="intense">Intense</button>
          </div>

          <div class="recommendation" id="recommendation">
            <strong>Suggested</strong>
            <ul id="program-list">
              <li>Loom Session — gentle collective</li>
              <li>Short Drift — restorative pause</li>
            </ul>
          </div>
        </div>

        <div class="hero-cta">
          <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="secondary" href="events.html">See gatherings</a>
        </div>
      </div>

      <svg class="pattern" aria-hidden="true"><use href="assets/img/pattern.svg#pattern"/></svg>
    </section>

    <section class="social-proof" id="proof">
      <div class="card glass">
        <h2>Voices & Signals</h2>
        <div class="proof-grid">
          <div class="testimonials" id="testimonials">
            <blockquote id="testimonial-text">"A calm workshop that keeps its promises." — R.</blockquote>
            <div class="t-controls">
              <button id="prev">◀</button>
              <button id="next">▶</button>
            </div>
          </div>
          <aside class="badges" id="badges">
            <div class="badge" data-tip="Local community award 2024">Community Pick</div>
            <div class="badge" data-tip="Featured in regional wellbeing guide">Regional Guide</div>
            <div class="badge" data-tip="Sanctioned pro-level facilitators">Certified</div>
          </aside>
        </div>
      </div>
    </section>

    <section class="benefits">
      <div class="card glass">
        <h2>Offerings reframed</h2>
        <p>Programs cast as moments: Loom Circles (group), Tide Rooms (deep drift), Private Resonance (one-to-one).</p>
        <ul>
          <li>Tune: brief grounding before daily tasks</li>
          <li>Sink: longer practices for deeper rest</li>
          <li>Hold: private sessions tailored to need</li>
        </ul>
        <div class="pricing-snapshot">
          <div><strong>Loom Circle</strong> — suggested donation, sliding scale</div>
          <div><strong>Tide Room</strong> — set fee, value-focused</div>
        </div>
      </div>
    </section>

    <section class="process">
      <div class="card glass">
        <h2>How a session moves</h2>
        <ol>
          <li>Arrive & settle — soft guidance</li>
          <li>Sound layering — bowls, flutes, voice</li>
          <li>Gentle return — reflection & support</li>
        </ol>
        <p class="note">Please read contraindications below before booking.</p>
      </div>
    </section>

    <section class="events" id="events">
      <div class="card glass">
        <h2>Next gatherings</h2>
        <div id="next-event"></div>
        <h3>Calendar</h3>
        <ul id="calendar-list"></ul>
        <a href="events.html" class="secondary">Full schedule</a>
      </div>
    </section>

    <section class="faq">
      <div class="card glass">
        <h2>Commonly asked</h2>
        <div class="qa">
          <details>
            <summary>Are these sessions safe for everyone?</summary>
            <p>Contraindications: If you have recent serious head injuries, pregnancy without approval, active psychosis, or implants sensitive to vibration, consult your clinician. Not a substitute for medical care.</p>
          </details>
          <details>
            <summary>What should I bring?</summary>
            <p>Comfortable layers, a mat if you like, and an intention. We provide blankets and bolsters when available.</p>
          </details>
        </div>
      </div>
    </section>

    <section class="cta">
      <div class="card glass">
        <h2>Reserve a space for sound</h2>
        <p>Step into a thoughtful pause. Book a place or ask about a private arrangement.</p>
        <a class="primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="light" href="book.html">Request private booking</a>
      </div>
    </section>
  </main>

  <footer>
    <div class="wrap">
      <div>{{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</div>
      <div>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      <div class="disclaimer">Not a replacement for medical advice.</div>
    </div>
  </footer>

  <script src="assets/js/main.js" defer></script>
</body>
</html>"} 
