{"path":"assets/css/styles.css","content":":root{
  --bg:#0c0f12;
  --glass-bg:rgba(255,255,255,0.06);
  --accent:#b7f0e6;
  --muted:#aab2b8;
  --card-radius:14px;
  --glass-border:rgba(255,255,255,0.08);
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; background:var(--bg);color:#eef1f2}
body{background-image:url('../assets/img/pattern.svg');background-repeat:repeat;background-size:220px;line-height:1.45}
.nav{display:flex;justify-content:space-between;align-items:center;padding:18px 28px}
.brand .logo{font-weight:700;color:var(--accent);text-decoration:none;font-size:1.1rem}
.brand .sub{display:block;font-size:0.78rem;color:var(--muted)}
nav a{color:var(--muted);margin-left:14px;text-decoration:none}
nav a.cta{background:linear-gradient(90deg,#79e6d0,#a0ffd9);color:#06201a;padding:8px 12px;border-radius:10px}
main{max-width:980px;margin:28px auto;padding:0 18px}
.card{padding:22px;border-radius:var(--card-radius);margin:20px 0}
.glass{background:var(--glass-bg);border:1px solid var(--glass-border);backdrop-filter:blur(8px);box-shadow:0 6px 18px rgba(0,0,0,0.5)}
.hero{position:relative;overflow:visible}
.pattern{position:absolute;right:-10px;top:-10px;width:220px;height:220px;opacity:0.07}
h1{margin:0 0 8px;font-size:1.6rem}
.lead{color:var(--muted);margin-top:0}
.mixer label{display:block;color:var(--muted);font-size:0.85rem;margin-bottom:8px}
.controls{display:flex;gap:8px;margin-bottom:12px}
.controls button{background:transparent;border:1px solid rgba(255,255,255,0.06);color:var(--muted);padding:8px 12px;border-radius:9px;cursor:pointer}
.controls button.active{background:linear-gradient(90deg, rgba(183,240,230,0.12), rgba(160,255,217,0.08));color:var(--accent);border-color:rgba(160,255,217,0.18)}
.recommendation{margin-top:6px;color:var(--muted)}
.recommendation ul{margin:6px 0 0 18px}
.hero-cta{margin-top:14px}
.primary{background:var(--accent);color:#05201a;padding:10px 16px;border-radius:12px;text-decoration:none;margin-right:8px}
.secondary{color:var(--muted);text-decoration:none;padding:10px}
.proof-grid{display:flex;gap:18px;align-items:center}
.testimonials{flex:1}
.testimonials blockquote{margin:0;font-size:1rem;color:#e8efee}
.t-controls{margin-top:10px}
.t-controls button{background:transparent;border:none;color:var(--muted);font-size:1.05rem;cursor:pointer;margin-right:6px}
.badges{display:flex;flex-direction:column;gap:8px}
.badge{background:transparent;border:1px solid rgba(255,255,255,0.04);padding:8px 10px;border-radius:8px;color:var(--muted);cursor:default}
.badge:hover{border-color:var(--glass-border);color:var(--accent)}
.tooltip{position:fixed;padding:8px 10px;background:#06201a;color:var(--accent);border-radius:8px;font-size:0.85rem;pointer-events:none;z-index:60;box-shadow:0 6px 18px rgba(0,0,0,0.6)}
.benefits ul{padding-left:18px}
.pricing-snapshot{margin-top:10px;color:var(--muted)}
.process ol{padding-left:18px}
.note{color:var(--muted);font-size:0.95rem}
.events #next-event{padding:12px;border-radius:10px;background:linear-gradient(180deg, rgba(255,255,255,0.02), rgba(255,255,255,0.01));margin-bottom:12px}
#calendar-list{list-style:none;padding-left:0}
#calendar-list li{padding:6px 0;border-bottom:1px dashed rgba(255,255,255,0.03);color:var(--muted)}
.cta .primary{display:inline-block}
footer{padding:18px;color:var(--muted);font-size:0.9rem}
.wrap{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap}
.disclaimer{font-size:0.8rem;color:#9aa3a7}
@media(max-width:720px){
  .proof-grid{flex-direction:column}
  nav{display:none}
  .pattern{display:none}
}
"} 
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Sound preference mixer
  const programs = {
    gentle:["Loom Session — soft layers","Short Drift — 30m guided rest","Dawn Circle — gentle bell"],
    medium:["Tide Room — 60m mixed tones","Evening Weave — voice & bowls","Flow Cluster — mid-intensity"],
    intense:["Deep Loom — extended vibration","Resonant Intensive — focused work","Nightfall Wave — immersive sound"]
  };
  const controls = document.querySelectorAll('#mixer .controls button');
  const programList = document.getElementById('program-list');
  function setIntensity(key){
    controls.forEach(b=>b.classList.toggle('active',b.dataset.intensity===key));
    programList.innerHTML = '';
    programs[key].forEach(p=>{
      const li = document.createElement('li'); li.textContent = p; programList.appendChild(li);
    });
  }
  controls.forEach(btn=>btn.addEventListener('click',()=>setIntensity(btn.dataset.intensity)));
  // default
  setIntensity('gentle');

  // Proof gallery (testimonials rotating) + badges tooltips
  const testimonials = [
    {text:'"I left lighter and more steady than I arrived." — A.'},
    {text:'"Clear, quiet, and exact in its care." — M.'},
    {text:'"A place that makes soft things possible." — S.'}
  ];
  let tIndex = 0;
  const tText = document.getElementById('testimonial-text');
  const prev = document.getElementById('prev');
  const next = document.getElementById('next');
  function showTestimonial(i){
    tIndex = (i+testimonials.length)%testimonials.length;
    tText.textContent = testimonials[tIndex].text;
  }
  prev.addEventListener('click',()=>showTestimonial(tIndex-1));
  next.addEventListener('click',()=>showTestimonial(tIndex+1));
  showTestimonial(0);
  let rot = setInterval(()=>showTestimonial(tIndex+1),6000);
  [prev,next].forEach(b=>b.addEventListener('click',()=>{clearInterval(rot);rot=setInterval(()=>showTestimonial(tIndex+1),6000);}));

  // Badges tooltips
  const badges = document.querySelectorAll('#badges .badge');
  let tipEl = null;
  badges.forEach(b=>{
    b.addEventListener('mouseenter',e=>{
      const tip = b.dataset.tip || '';
      if(!tip) return;
      tipEl = document.createElement('div'); tipEl.className='tooltip'; tipEl.textContent = tip; document.body.appendChild(tipEl);
    });
    b.addEventListener('mousemove',e=>{
      if(!tipEl) return; tipEl.style.left = (e.pageX+12)+'px'; tipEl.style.top = (e.pageY+12)+'px';
    });
    b.addEventListener('mouseleave',()=>{ if(tipEl){ tipEl.remove(); tipEl=null; } });
  });

  // Events module: next-event + calendar list
  const rawEvents = [
    {title:'Loom Circle',date:'2026-03-01T18:30:00',location:'Main Space'},
    {title:'Tide Room — Long Drift',date:'2026-03-08T19:00:00',location:'Main Space'},
    {title:'Private Resonance (limited)',date:'2026-03-14T10:00:00',location:'Private Room'},
    {title:'Community Open Session',date:'2026-03-21T17:30:00',location:'Main Space'}
  ];
  const now = new Date();
  const upcoming = rawEvents.map(e=>Object.assign({},e,{dt:new Date(e.date)})).filter(e=>e.dt>now).sort((a,b)=>a.dt-b.dt);
  const nextEventEl = document.getElementById('next-event');
  const calList = document.getElementById('calendar-list');
  if(upcoming.length>0){
    const n = upcoming[0];
    nextEventEl.innerHTML = '<strong>'+n.title+'</strong><div style="color:var(--muted);">'+n.dt.toLocaleString()+' • '+n.location+'</div>';
    upcoming.forEach(ev=>{
      const li = document.createElement('li');
      li.textContent = ev.dt.toLocaleDateString() + ' — ' + ev.title + ' (' + ev.location + ')';
      calList.appendChild(li);
    });
  } else {
    nextEventEl.textContent = 'No events scheduled yet. Check back soon.';
  }

  // Accessibility small helpers
  // attach keyboard control to mixer
  document.querySelectorAll('#mixer .controls button').forEach((btn,i,arr)=>{
    btn.addEventListener('keydown',e=>{
      if(e.key==='ArrowRight'){ e.preventDefault(); arr[(i+1)%arr.length].focus(); }
      if(e.key==='ArrowLeft'){ e.preventDefault(); arr[(i-1+arr.length)%arr.length].focus(); }
    });
  });

});"} 
